<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Track Booking | Mi Cusina</title><link rel="stylesheet" href="{{ asset('assets/vendors/themify-icons/css/themify-icons.css') }}"><style>body{font-family:Arial,sans-serif;margin:2rem auto;max-width:680px;color:#222}.card{border:1px solid #ddd;border-radius:12px;padding:1.5rem}.notice{padding:.8rem;background:#fff7e6;border-left:3px solid #e69b00}button{background:#b91c1c;color:#fff;border:0;border-radius:5px;padding:.65rem 1rem}</style></head><body><a href="{{ route('bookings.index') }}">← My bookings</a><div class="card"><h1><i class="ti-calendar"></i> Track Booking</h1><p><strong>Reservation status:</strong> <span id="reservationStatus">{{ $booking->status }}</span></p><p><strong>Payment status:</strong> <span id="paymentStatus">{{ $booking->payment_status }}</span></p><p>{{ $booking->date }} at {{ $booking->time }} · {{ $booking->guest }} guest(s)</p>@php($canCancel = !in_array($booking->status,['Completed','Canceled'],true)) @if($canCancel)<p class="notice" title="Reservation downpayments are non-refundable"><i class="ti-info-alt"></i> Please note: Reservation downpayments are non-refundable.</p><form method="POST" action="{{ route('bookings.cancel',$booking) }}" onsubmit="return confirm('Cancel this reservation?');">@csrf<button title="Cancel Booking" aria-label="Cancel Booking"><i class="ti-close"></i> Cancel Reservation</button></form>@endif</div><script>var last=@json($booking->updated_at?->toIso8601String());setInterval(function(){fetch(@json(url('track_booking',$booking->id).'/status'),{headers:{Accept:'application/json'}}).then(r=>r.ok?r.json():null).then(d=>{if(d&&d.updated_at!==last)location.reload()}).catch(()=>{})},15000)</script></body></html>
